<script setup>import {ref,onMounted,onUnmounted} from 'vue';import {addStorage,watchStorage,removeStorage} from '../services/data';const props=defineProps(['user']);const emit=defineEmits(['toast']);const name=ref(''),url=ref(''),items=ref([]);let stop;onMounted(()=>stop=watchStorage(props.user.uid,v=>items.value=v));onUnmounted(()=>stop?.());async function add(){try{if(!name.value.trim()||!/^https?:\/\//i.test(url.value))throw Error('Servis adı ve geçerli https/http linki gerekli.');await addStorage(props.user.uid,name.value.trim(),url.value.trim());name.value='';url.value='';emit('toast','Depolama bağlantısı eklendi.')}catch(e){emit('toast',e.message)}}async function remove(id){await removeStorage(props.user.uid,id);emit('toast','Bağlantı kaldırıldı.')}</script><template><h1>Kişisel Depolama Bağlantılarım</h1><p class="muted">Bu sayfa yalnızca senin hesabın tarafından okunabilir. FlameStore ana uygulama dosyalarını barındırmaz.</p><div class="card"><h2>Yeni bağlantı</h2><div class="grid"><input class="field" v-model="name" placeholder="Google Drive / MEGA / GitHub Releases"><input class="field" v-model="url" placeholder="https://..." type="url"></div><button class="btn" @click="add">Bağlantı ekle</button></div><br><div class="list"><div v-for="x in items" :key="x.id" class="list-item space"><div><b>{{x.name}}</b><br><a :href="x.url" target="_blank" rel="noopener noreferrer" class="muted">{{x.url}}</a></div><button class="btn secondary" @click="remove(x.id)">Kaldır</button></div><div v-if="!items.length" class="card empty">Henüz depolama bağlantın yok.</div></div></template>